const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountJourneyMap(host,farm,crop){let active=0;const same=farm.crop?.startsWith(crop.name),annual=crop.name==='Arroz';
const nodes=[{icon:'🏡',title:'Tu punto de partida',text:'Cultivo registrado en el escenario: '+farm.crop+'. Confirma que corresponde a tu finca.'},{icon:'🔎',title:'Antes de cambiar',text:'Comprueba suelo, riego y clima. La consulta NASA y el análisis de campo están debajo del mapa; explorar este camino no valida esos requisitos.'},{icon:crop.symbol,title:same?'Adaptar '+crop.name:annual?'Preparar una campaña de arroz':'Evaluar el cambio a '+crop.name,text:same?'Conserva la plantación mientras revisas las medidas de manejo con tu técnico.':annual?'Solo en un lote anual compatible y con agua confirmada. No se propone arrancar los frutales.':'Es una posible reconversión de largo plazo. Revisar inversión, variedad y viabilidad antes de modificar la plantación.'},{icon:'🌱',title:same?'Aplicar el plan acordado':'Establecer solo si es viable',text:'Esta etapa requiere evaluación agronómica previa. Fechas, labores y cantidades deben definirse para tu terreno.'},{icon:'📒',title:annual?'Cosechar y decidir la siguiente campaña':'Observar, registrar y ajustar',text:annual?'Registrar resultados y volver a evaluar el siguiente cultivo. No se ha validado una secuencia de rotación posterior.':'Seguir la plantación durante varias campañas. No es una rotación anual; el tiempo hasta producción aún no está calculado.'}];
host.innerHTML='<section class="quest-map"><div class="quest-caption"><span>EXPLORA UN CAMINO POSIBLE</span><h3>'+esc(farm.crop)+' → '+(same?'mantener y adaptar':esc(crop.name))+'</h3><p>'+(same?'Manejo de la plantación':annual?'Campaña en lote anual separado':'Reconversión a largo plazo')+' · Sin calendario ni aptitud validados</p></div><div class="quest-land"><svg viewBox="0 0 1000 420" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="questground" x2="0" y2="1"><stop stop-color="#8db580"/><stop offset="1" stop-color="#456e48"/></linearGradient></defs><path d="M0 100Q170 15 330 85T660 80T1000 75V420H0Z" fill="url(#questground)"/><path d="M0 340Q250 230 430 340T1000 285" fill="none" stroke="#7bc8c8" stroke-width="27"/><path d="M90 240Q180 240 285 140T490 240T700 145T910 240" fill="none" stroke="#d4bd88" stroke-width="28"/><path class="quest-trail" d="M90 240Q180 240 285 140T490 240T700 145T910 240" fill="none" stroke="#fff3c2" stroke-width="3" stroke-dasharray="6 13"/></svg><div class="quest-cloud cloud-one">☁</div><div class="quest-cloud cloud-two">☁</div><div class="quest-stops">'+nodes.map((n,i)=>'<button type="button" data-stop="'+i+'" style="--position:'+i+'"><span class="quest-node">'+n.icon+'</span><small>PARADA '+(i+1)+'</small><strong>'+n.title+'</strong></button>').join('')+'</div></div><div class="quest-info" aria-live="polite"></div><div class="quest-controls"><button type="button" class="quest-back">← Anterior</button><span class="quest-progress"></span><button type="button" class="quest-forward">Siguiente parada →</button></div><p class="quest-disclaimer">Mapa conceptual, no mapa geográfico. Las paradas muestran el proceso; no son tareas cumplidas ni autorizaciones de siembra. Cambia de alternativa arriba para comparar otros caminos.</p></section>';
function update(){host.querySelectorAll('[data-stop]').forEach(el=>{el.setAttribute('aria-current',Number(el.dataset.stop)===active?'step':'false');});host.querySelector('.quest-info').innerHTML='<h4>'+nodes[active].icon+' '+nodes[active].title+'</h4><p>'+esc(nodes[active].text)+'</p>';host.querySelector('.quest-back').disabled=active===0;host.querySelector('.quest-forward').textContent=active===4?'Recorrer otra vez ↺':'Siguiente parada →';host.querySelector('.quest-progress').textContent=(active+1)+' / 5';}
host.querySelectorAll('[data-stop]').forEach(el=>el.onclick=()=>{active=Number(el.dataset.stop);update()});host.querySelector('.quest-back').onclick=()=>{active=Math.max(0,active-1);update()};host.querySelector('.quest-forward').onclick=()=>{active=(active+1)%5;update()};update();}
